import { getDocumentContentForSummarizer } from "../common/utils";
import { Message } from "../common/types";
import { GOOGLE_CHROME_PDF_VIEWER_EXTENSION_URL } from "../common/constants";

chrome.runtime.onMessage.addListener(
  (message: Message, _sender: chrome.runtime.MessageSender, sendResponse: (message: Message) => void) => {
    if (document.contentType === "text/html") {
      if (message.type === "requestHtmlOrPdfDocument") {
        const documentClone: Document = document.implementation.createHTMLDocument();
        documentClone.documentElement.innerHTML = document.documentElement.innerHTML;

        documentClone.documentElement.querySelectorAll("svg, style").forEach((elem: Element) => {
          elem.remove();
        });

        documentClone.documentElement.querySelectorAll("script").forEach((elem: Element) => {
          if (elem.hasAttribute("type") && elem.getAttribute("type") === "application/ld+json") {
            // keep schema.org scripts
          } else {
            elem.remove();
          }
        });

        sendResponse({
          type: "htmlDocument",
          html: documentClone.documentElement.outerHTML,
          url: document.URL,
        });
      }

      if (message.type === "requestDocumentContent") {
        sendResponse({
          type: "documentContent",
          documentContent: getDocumentContentForSummarizer(document),
        });
      }
    }
    if (document.contentType === "application/pdf") {
      if (message.type === "requestHtmlOrPdfDocument") {
        selectAndCopyPdfPageContents().then((contents) =>
          sendResponse({
            type: "pdfDocument",
            url: window.location.href,
            contents,
          }),
        );
        return true;
      }
    }
    return void 0;
  },
);

function selectAndCopyPdfPageContents() {
  return new Promise<string | undefined>((resolve) => {
    window.addEventListener("message", function onMessage(e) {
      // https://source.chromium.org/chromium/chromium/src/+/main:chrome/browser/resources/pdf/pdf_scripting_api.ts;l=122-127
      if (e.origin === GOOGLE_CHROME_PDF_VIEWER_EXTENSION_URL && e.data?.type === "getSelectedTextReply") {
        window.removeEventListener("message", onMessage);
        resolve(e.data.selectedText ?? undefined);
      }
    });
    // runs code in page context to access postMessage of the embedded plugin
    const script = document.createElement("script");
    script.src = chrome.runtime.getURL("pdf-injection.js");
    document.documentElement.appendChild(script);
    script.remove();
  });
}
