function getBrowserLanguage() {
  if (typeof navigator !== "undefined") {
    if (navigator.languages && navigator.languages.length > 0) {
      return navigator.languages[0];
    }

    if (navigator.language) {
      return navigator.language;
    }
  }

  return undefined;
}

export function getLocale(): Locale {
  const browserLanguage = getBrowserLanguage();

  if (browserLanguage != undefined) {
    if (isLocale(browserLanguage)) {
      return browserLanguage;
    }

    for (const locale of Locales) {
      if (locale.startsWith(browserLanguage)) {
        return locale;
      }
    }
  }

  return defaultLocale;
}

export const getCitationStyleTranslation = (
  citationStyle: CitationStyle,
  t: TFunction,
  form: "short" | "long" = "long",
) => {
  if (isPromotedCitationStyle(citationStyle)) {
    const key = camelCase([...citationStyle].filter(Boolean).join("-"));

    switch (form) {
      case "short":
        return t(`citationStyles.short.${key}`);
      case "long":
        return t(`citationStyles.${key}`);
      default:
        throw new UnreachableCaseError(form);
    }
  } else {
    return getUnverifiedCitationStyleTitle(citationStyle);
  }
};

// direct copy from QBs extension
function removeAuthorAndSiteName({ title, byline: author, siteName }: ReadabilityArticle) {
  if (
    title.includes(author) &&
    title.includes(siteName) &&
    document.querySelectorAll('meta[property="og:title"]')[0]?.getAttribute("content") !== title
  ) {
    return title
      .substring(0, title.lastIndexOf(siteName))
      .substring(0, title.lastIndexOf(author))
      .replaceAll(" - ", "")
      .trim();
  } else {
    return title;
  }
}

// direct copy from QBs extension
export function getDocumentContentForSummarizer(document: Document): DocumentContent | undefined {
  const documentClone: Document = document.implementation.createHTMLDocument();
  documentClone.documentElement.innerHTML = document.documentElement.innerHTML;

  const article = new Readability(documentClone).parse();

  if (!article) {
    return;
  }

  const cleanedDocumentClone = document.implementation.createHTMLDocument();
  cleanedDocumentClone.documentElement.innerHTML = article.content;

  // add line breaks to preserve newlines in the text
  cleanedDocumentClone.body.querySelectorAll("p, h1, h2, h3, h4, h5, h6, section").forEach((elem: Element) => {
    elem.innerHTML = elem.innerHTML + "$$INS_NL_QB$$";
  });

  // remove image captions
  cleanedDocumentClone.body.querySelectorAll("figcaption").forEach((elem: Element) => {
    elem.remove();
  });

  // remove code blocks
  cleanedDocumentClone.body.querySelectorAll("pre").forEach((elem: Element) => {
    elem.remove();
  });

  // globally replace $$INS_NL_QB$$ with \n in articleText
  const articleText = cleanedDocumentClone.body.innerText.replace(/\$\$INS_NL_QB\$\$/g, "\n");

  return { content: articleText, title: removeAuthorAndSiteName(article) };
}

const isValidHistoryEntry = (x: unknown): x is HistoryEntry => HistoryEntrySchema.safeParse(x).success;

export async function fetchHistory(): Promise<HistoryEntry[]> {
  const result = await chrome.storage.local.get(HISTORY_LOCAL_STORAGE_KEY);
  const results: unknown[] = result[HISTORY_LOCAL_STORAGE_KEY] ?? [];
  const history = results.filter(isValidHistoryEntry);
  history.sort((a, b) => b.timestamp - a.timestamp);
  return history;
}

export async function saveHistory(history: HistoryEntry[]): Promise<void> {
  await chrome.storage.local.set({ [HISTORY_LOCAL_STORAGE_KEY]: history });
}

export async function upsertSourceToHistory(source: Source, id: string): Promise<void> {
  const history = await fetchHistory();

  // first we check if the source with citation already exists in the history
  // if we find it, we update the timestamp
  let isExistingSource = false;
  const updatedHistory = history.map((entry) => {
    if (entry.id === id) {
      isExistingSource = true;
      return {
        ...entry,
        timestamp: Date.now(),
      };
    }
    return entry;
  });

  // if it was an existing source, just save the updated history
  if (isExistingSource) {
    return await saveHistory(updatedHistory);
  }

  // otherwise, we take the first HISTORY_LIMIT - 1 entries, and add the new one to the front
  const bufferedHistory = updatedHistory.slice(0, HISTORY_LIMIT - 1);

  await saveHistory([
    {
      id,
      timestamp: Date.now(),
      isEditedSource: false,
      version: "1" as const,
      source,
    },
    ...bufferedHistory,
  ]);
}

export async function editSourceInHistory(source: Source, id: string): Promise<void> {
  const history = await fetchHistory();
  const historyEntry = history.find((entry) => entry.id === id);
  if (!historyEntry) {
    throw new Error("Source not found in history");
  }

  const updatedHistory: Array<HistoryEntry> = history.map((entry) => {
    if (entry.id === id) {
      return {
        ...entry,
        source,
        timestamp: Date.now(),
        isEditedSource: true,
      };
    }
    return entry;
  });

  await saveHistory(updatedHistory);
}

export const isBadgeHidden = (settings: Settings, urlOrigin: string) => {
  return settings.hideBadgeForAllOrigins || settings.hiddenBadgeOrigins?.includes(urlOrigin);
};

export function getCreateNewListURL(domain: Domain, env: ScribbrEnv, folderId: ID) {
  const routes = new RouteBuilder(domain);
  return routes.lists(folderId).create().getHref(env);
}

export async function getActiveTab(): Promise<chrome.tabs.Tab & { id: number; url: string }> {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });

  if (!tab || !tab.id || !tab.url) {
    throw new Error("No active tab");
  }

  return { ...tab, id: tab.id, url: tab.url };
}
